package com.shopstream.order;

import java.nio.charset.StandardCharsets;
import java.util.concurrent.CompletableFuture;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.support.SendResult;
import org.springframework.stereotype.Component;

@Component
public class OrderEventPublisher {

    private final KafkaTemplate<String, Object> kafka;

    public OrderEventPublisher(KafkaTemplate<String, Object> kafka) {
        this.kafka = kafka;
    }

    public CompletableFuture<SendResult<String, Object>> publish(
            String orderId, String type, Object event) {
        var record = new ProducerRecord<String, Object>("orders", orderId, event);
        record.headers().add("event-type", type.getBytes(StandardCharsets.UTF_8));
        return kafka.send(record);
    }
}

