package com.shopstream.shipping;

import com.shopstream.events.Customer;
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.stereotype.Component;

@Component
public class CustomerViewUpdater {

    private final JdbcClient jdbc;

    public CustomerViewUpdater(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @KafkaListener(topics = "customers", groupId = "shipping-service")
    public void onCustomer(ConsumerRecord<String, Customer> record) {
        String customerId = record.key();
        Customer customer = record.value();
        if (customer == null) {
            // a tombstone: the customer was deleted at the source
            jdbc.sql("DELETE FROM customer_view WHERE customer_id = :id")
                .param("id", customerId)
                .update();
            return;
        }
        jdbc.sql("""
                INSERT INTO customer_view (customer_id, name, tier, city)
                VALUES (:id, :name, :tier, :city)
                ON CONFLICT (customer_id)
                DO UPDATE SET name = :name, tier = :tier, city = :city
                """)
            .param("id", customerId)
            .param("name", customer.name())
            .param("tier", customer.tier())
            .param("city", customer.city())
            .update();
    }
}

@Transactional
public Order placeOrder(PlaceOrderRequest request) {
    Order order = orders.save(Order.create(request));              // write 1: database
    kafka.send("orders", order.getId(), OrderCreated.from(order)); // write 2: Kafka
    return order;
}

@Transactional
public Order placeOrder(PlaceOrderRequest request) {
    Order order = orders.save(Order.create(request));          // business row
    outbox.add("orders", order.getId(), "ORDER_CREATED",
            OrderCreated.from(order));                          // outbox row, same transaction
    return order;
}

@Transactional(propagation = Propagation.MANDATORY)
public void add(String topic, String key, String type, DomainEvent event) {
    jdbc.sql("""
            INSERT INTO outbox (id, aggregatetype, aggregateid, type, payload)
            VALUES (:id, :topic, :key, :type, CAST(:payload AS jsonb))
            """)
        .param("id", UUID.fromString(event.eventId()))
        .param("topic", topic)
        .param("key", key)
        .param("type", type)
        .param("payload", json.writeValueAsString(event))
        .update();
}

@Scheduled(fixedDelay = 500)
@Transactional
public void relay() {
    List<OutboxRow> batch = jdbc.sql("""
            SELECT id, aggregatetype, aggregateid, type, CAST(payload AS text) AS payload
            FROM outbox
            WHERE published_at IS NULL
            ORDER BY created_at, id
            LIMIT 100
            FOR UPDATE SKIP LOCKED
            """)
        .query((rs, n) -> new OutboxRow(rs.getObject("id", UUID.class),
                rs.getString("aggregatetype"), rs.getString("aggregateid"),
                rs.getString("type"), rs.getString("payload")))
        .list();

    List<CompletableFuture<?>> sends = new ArrayList<>();
    for (OutboxRow row : batch) {
        var record = new ProducerRecord<>(row.topic(), row.key(), row.payload());
        record.headers().add("event-id", row.id().toString().getBytes(UTF_8));
        sends.add(kafka.send(record));
    }
    sends.forEach(CompletableFuture::join);       // a failed send throws and rolls back

    batch.forEach(row -> jdbc.sql("UPDATE outbox SET published_at = now() WHERE id = :id")
            .param("id", row.id()).update());
}

@Configuration
public class ConsumerErrorConfig {

    @Bean
    DefaultErrorHandler errorHandler(KafkaTemplate<Object, Object> template) {
        var recoverer = new DeadLetterPublishingRecoverer(template);
        var handler = new DefaultErrorHandler(recoverer, new FixedBackOff(1000L, 2L));
        handler.addNotRetryableExceptions(IllegalArgumentException.class);
        return handler;
    }
}

@Component
public class NotificationListener {

    private static final Logger log = LoggerFactory.getLogger(NotificationListener.class);

    private final EmailGateway gateway;

    public NotificationListener(EmailGateway gateway) {
        this.gateway = gateway;
    }

    @RetryableTopic(attempts = "4", backOff = @BackOff(delay = 5000),
            exclude = IllegalArgumentException.class)
    @KafkaListener(topics = "notifications", groupId = "notification-service")
    public void on(NotificationRequested request) {
        gateway.send(request);   // a RuntimeException moves the record to the retry topic
    }

    @DltHandler
    public void onDead(NotificationRequested request) {
        log.error("Notification {} could not be delivered", request.eventId());
    }
}

@Component
public class DltReplayer {

    private final KafkaTemplate<String, String> kafka;

    public DltReplayer(KafkaTemplate<String, String> kafka) {
        this.kafka = kafka;
    }

    @KafkaListener(id = "orders-dlt-replayer", topics = "orders-dlt", autoStartup = "false")
    public void replay(ConsumerRecord<String, String> record) {
        Header origin = record.headers().lastHeader(KafkaHeaders.DLT_ORIGINAL_TOPIC);
        String topic = new String(origin.value(), StandardCharsets.UTF_8);
        var out = new ProducerRecord<>(topic, null, record.key(), record.value());
        for (Header h : record.headers()) {
            if (!h.key().startsWith("kafka_dlt-")) {
                out.headers().add(h);              // keeps type headers and the eventId
            }
        }
        kafka.send(out).join();
    }
}

@Transactional
@KafkaHandler
public void on(StockReserved event) {
    OrderSaga saga = sagas.require(event.orderId());
    if (saga.state() != SagaState.AWAITING_STOCK) {
        return;                                    // duplicate or late event: ignore
    }
    saga.moveTo(SagaState.AWAITING_PAYMENT, Instant.now().plus(Duration.ofMinutes(5)));
    outbox.add("payment-commands", saga.orderId(), "AUTHORIZE_PAYMENT",
            AuthorizePayment.of(saga));
}

public sealed interface OrderEvent extends DomainEvent
        permits OrderCreated, OrderConfirmed, OrderCancelled { }

public record OrderState(String orderId, String status, BigDecimal total) {

    /** Rebuild the state by folding the history, oldest event first. */
    public static OrderState replay(List<OrderEvent> history) {
        OrderState state = null;
        for (OrderEvent event : history) {
            state = apply(state, event);
        }
        return state;
    }

    private static OrderState apply(OrderState state, OrderEvent event) {
        return switch (event) {
            case OrderCreated e -> new OrderState(e.orderId(), "PENDING", e.total());
            case OrderConfirmed e -> new OrderState(state.orderId(), "CONFIRMED", state.total());
            case OrderCancelled e -> new OrderState(state.orderId(), "CANCELLED", state.total());
        };
    }

    /** The command: decide which events follow, or reject. */
    public List<OrderEvent> confirm(Instant now) {
        if (!"PENDING".equals(status)) {
            throw new IllegalStateException("Order " + orderId + " is " + status);
        }
        return List.of(new OrderConfirmed(UUID.randomUUID().toString(), orderId, now));
    }
}

@KafkaHandler
public void on(OrderCreated event) {
    jdbc.sql("""
            INSERT INTO order_summary (order_id, customer_id, total, status)
            VALUES (:id, :customer, :total, 'PENDING')
            ON CONFLICT (order_id) DO NOTHING
            """)
        .param("id", event.orderId())
        .param("customer", event.customerId())
        .param("total", event.total())
        .update();
}

@KafkaHandler
public void on(OrderConfirmed event) {
    jdbc.sql("UPDATE order_summary SET status = 'CONFIRMED' WHERE order_id = :id")
        .param("id", event.orderId())
        .update();
}
